messages.content:
{
  "matches": [
    {
      "id": "tool:bash",
      "kind": "tool",
      "name": "bash",
      "description": "Execute a command in the shell and return combined stdout/stderr.",
      "status": "ready",
      "input_schema": {
        "type": "object",
        "properties": {
          "command": {
            "type": "string",
            "description": "Shell command to execute"
          },
          "description": {
            "type": "string",
            "description": "Optional short name for this call, in the user's language, shown in task lists."
          },
          "run_in_background": {
            "type": "boolean",
            "description": "Run detached: returns a job id immediately and keeps running across turns (no foreground timeout). Read new output with bash_output, wait with wait, stop it with kill_shell. Use for long-running commands like servers, watchers, or builds you don't need to block on."
          },
          "preserve_background_processes": {
            "type": "boolean",
            "description": "After the shell command exits normally, keep any process-group members it intentionally left behind. Use only for deliberate daemonization, browser/GUI/session launchers such as playwright-cli open, or nohup/disown/setsid; cancellation and timeouts still kill the process group."
          },
          "timeout_seconds": {
            "type": "integer",
            "description": "Deadline for this foreground call. Only tightens the host cap — a larger value is clamped to it. Output collected before the deadline is still returned, so set it low when a command's cost is unpredictable (a broad filesystem walk, a network fetch) instead of paying the full cap to find out. For work that legitimately runs long, use run_in_background.",
            "minimum": 1
          },
          "verifies": {
            "type": "string",
            "description": "Name what this call decides (e.g. \"balances.json keys are sorted\") to record it as a check. The exit status becomes the verdict, so the command must be one command or an \u0026\u0026 chain; a ';', a pipe, or '||' hands the status to something else and the call is refused."
          }
        },
        "required": [
          "command"
        ]
      }
    },
    {
      "id": "tool:kill_shell",
      "kind": "tool",
      "name": "kill_shell",
      "description": "Terminate a running background job (bash or task) started with run_in_background.",
      "status": "ready",
      "input_schema": {
        "type": "object",
        "properties": {
          "job_id": {
            "type": "string",
            "description": "The background job id to terminate (e.g. \"bash-1\")."
          }
        },
        "required": [
          "job_id"
        ]
      }
    },
    {
      "id": "tool:conclude_blocked",
      "kind": "tool",
      "name": "conclude_blocked",
      "description": "Declare that part of the task cannot be completed as specified, after you have established why.",
      "status": "ready",
      "read_only": true,
      "input_schema": {
        "type": "object",
        "properties": {
          "blocker": {
            "type": "string",
            "description": "What cannot be done and why it cannot. Shown to the user."
          },
          "criterion_id": {
            "type": "string",
            "description": "Optional id of the acceptance criterion that cannot be met."
          },
          "evidence": {
            "type": "array",
            "minItems": 1,
            "description": "What you ran or read that establishes the blocker. At least one must match a receipt from this turn.",
            "items": {
              "type": "object",
              "properties": {
                "command": {
                  "type": "string",
                  "description": "A command you ran this turn, exactly as it ran. A command that failed is evidence too."
                },
                "paths": {
                  "type": "array",
                  "items": {
                    "type": "string"
                  },
                  "description": "Files you read or wrote this turn."
                }
              }
            }
          }
        },
        "required": [
          "blocker",
          "evidence"
        ]
      }
    },
    {
      "id": "tool:task",
      "aliases": [
        "task:subagent"
      ],
      "kind": "tool",
      "name": "task",
      "description": "Spawn a sub-agent for a focused sub-task.",
      "status": "ready",
      "input_schema": {
        "type": "object",
        "properties": {
          "prompt": {
            "type": "string",
            "description": "What the sub-agent should accomplish. Be specific about the deliverable — the sub-agent does not see this conversation."
          },
          "description": {
            "type": "string",
            "description": "Short label for the sub-task (3-7 words). Surfaced in the dispatch line so the user sees what's running."
          },
          "profile": {
            "type": "string",
            "description": "Optional runAs=subagent profile name. Resolved at runtime from the Skill store; explicit names may invoke invocation=manual profiles. The profile body becomes the full system prompt."
          },
          "write_paths": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "description": "Optional workspace-relative or absolute file/directory paths this writer may modify. Prefer file paths when the targets are known: a directory overlaps every path beneath it and serializes writers. Globs and workspace escapes are rejected. Writers without write_paths claim the whole workspace (serializing against every other writer claim) unless write_lease is optimistic. Non-overlapping paths allow parallel writers up to max_parallel_writers. In fleet, multiple whole-workspace claims fail preflight before any task starts."
          },
          "tools": {
            "type": "array",
            "items": {
              "type": "string"
            },
            "description": "Optional tool whitelist. When profile sets allowed-tools, this list is intersected (call args cannot expand profile permissions). Recursive agent/skill tools are exposed only while max_subagent_depth leaves another delegation layer; unsupported background job tools (parallel_tasks, wait, bash_output, kill_shell) are excluded; bash is exposed as foreground-only inside subagents."
          },
          "max_steps": {
            "type": "integer",
            "description": "Optional cap on tool-call rounds. Defaults to half the parent's cap (min 5).",
            "minimum": 1
          },
          "run_in_background": {
            "type": "boolean",
            "description": "Run the sub-agent asynchronously: returns a job id immediately and keeps working across turns. Collect its final answer with wait, and you'll be notified when it finishes. Use for long, independent sub-tasks you don't need to block on right now."
          },
          "model": {
            "type": "string",
            "description": "Optional model override for the sub-agent (a configured provider/model name). Precedence: persistent profile config, this argument, profile frontmatter, global subagent default, parent model."
          },
          "effort": {
            "type": "string",
            "description": "Optional reasoning effort for the sub-agent (e.g. high, max). Same precedence as model."
          },
          "continue_from": {
            "type": "string",
            "description": "Continue a prior compatible subagent transcript in the current conversation context. Pass only the 'sa_...' value from the prior result's 'Subagent reference: ...' line. If the ref belongs to an ancestor conversation, the framework continues a current-conversation copy."
          },
          "task_id": {
            "type": "string",
            "description": "Send this call's prompt as guidance to a sub-agent that is still running, instead of starting a new one. Pass the 'sa_...' value from its 'Subagent reference: ...' line. The sub-agent reads it at its next tool call, framed as coming from you and not from the user; it changes nothing about what the sub-agent is allowed to do. If that sub-agent has already finished, the call continues its transcript exactly as continue_from does."
          }
        },
        "required": [
          "prompt"
        ]
      }
    },
    {
      "id": "tool:bash_output",
      "kind": "tool",
      "name": "bash_output",
      "description": "Read new output from a background job started with bash(run_in_background=true) or task(run_in_background=true).",
